sed -i 's|if($("studioCenterObjBtn")) $("studioCenterObjBtn").onclick=()=>apply(()=>{const p=studioPage(); const o=studioObject(); if(!o)return; o.x=Math.round((p.w-o.w)/2); o.y=Math.round((p.h-o.h)/2);},true,"Objet centré");|const alignStudioObject=(alignType)=>{const o=studioObject();const p=studioPage();if(!o||!p)return;apply(()=>{if(alignType==="left")o.x=0;if(alignType==="hcenter")o.x=Math.round((p.w-o.w)/2);if(alignType==="right")o.x=p.w-o.w;if(alignType==="top")o.y=0;if(alignType==="vcenter")o.y=Math.round((p.h-o.h)/2);if(alignType==="bottom")o.y=p.h-o.h;},true,"Alignement "+alignType);};\n  if($("studioAlignLeftBtn"))$("studioAlignLeftBtn").onclick=()=>alignStudioObject("left");\n  if($("studioAlignHCenterBtn"))$("studioAlignHCenterBtn").onclick=()=>alignStudioObject("hcenter");\n  if($("studioAlignRightBtn"))$("studioAlignRightBtn").onclick=()=>alignStudioObject("right");\n  if($("studioAlignTopBtn"))$("studioAlignTopBtn").onclick=()=>alignStudioObject("top");\n  if($("studioAlignVCenterBtn"))$("studioAlignVCenterBtn").onclick=()=>alignStudioObject("vcenter");\n  if($("studioAlignBottomBtn"))$("studioAlignBottomBtn").onclick=()=>alignStudioObject("bottom");|g' app.js
